arguments.command:
cd .state/sessions/history && for d in $(ls -t | head -80); do [ -f "$d/meta.json" ] && python3 -c "
import json,os; m=json.load(open('$d/meta.json'))
size=os.path.getsize('$d/session.jsonl') if os.path.exists('$d/session.jsonl') else 0
if size > 200000: print(f'LARGE: $d {m.get(\"agent\",\"?\")} {size}B')
if m.get('error'): print(f'ERROR: $d {m.get(\"agent\",\"?\")} {m.get(\"error\",\"\")[:60]}')
" 2>/dev/null; done

content.text:
{
  "type": "list",
  "workflows": [
    {
      "name": "design-review",
      "description": "Review shared knowledge docs against reality. Evaluator and optimizer independently review, then cross-respond. Returns structured findings for the optimizer to act on."
    },
    {
      "name": "enhance-cron",
      "description": "Safely extend the Cron system with a new capability. Structured pipeline: state → methods → lifecycle hook → context exposure. Tests run after every step. Task should describe the new feature."
    },
    {
      "name": "implement-and-review",
      "description": "Implement a fix, then review. One retry for fixable issues. Escalates on critical review issues or second rejection."
    },
    {
      "name": "safe-edit",
      "description": "Safely edit a file using size-aware strategy. Small files (<300 lines) get full read/write via LLM. Large files (≥300 lines) get surgical grep+sed edits. Task format: JSON with 'path' and 'change_description' fields."
    },
    {
      "name": "verify-parallel",
      "description": "L3 Kinetic Defense: Coder implements, then QA + adversarial Auditor review in parallel. Auditor uses contrastive framing to break consensus hallucination. Escalates if Auditor finds issues QA missed."
    },
    {
      "name": "skill-lifecycle",
      "description": "Full skill lifecycle: discover pattern → draft SKILL.md → test in gym → deploy. Each phase is a separate session to prevent skipping steps. Task: describe what kind of pattern to look for. Optional 'agent: <name>' header (default: optimizer)."
    },
    {
      "name": "two-phase",
      "description": "Two-phase workflow enforcement: run analysis in one session, action in another. Phases communicate only through artifacts on disk. Task format: phase1 instructions, then ---, then phase2 instructions. Optional 'agent: <name>' header (default: coder)."
    }
  ]
}

